const DEFINED = Symbol.for("jshack:shopDebtVirtuals:defined");
const SHOP_DEBT_VIEW_KEY = Symbol.for("jshack:shopDebtVirtuals:ShopDebtView");

function getShopDebtVirtual(world) {
