  for (const debtId of children(world, actorId | 0)) {
    const debt = /** @type any */ (world.get(debtId, ShopDebt));
    if (!debt || String(debt.status || SHOP_DEBT_STATUS.unpaid) !== SHOP_DEBT_STATUS.unpaid) continue;
